const overlay=document.querySelector('#missionTransit'),canvas=document.querySelector('#missionTransitCanvas'),ctx=canvas?.getContext('2d');
const title=document.querySelector('#transitTitle'),brief=document.querySelector('#transitBrief'),code=document.querySelector('#transitCode'),bar=document.querySelector('#transitBar'),value=document.querySelector('#transitValue'),left=document.querySelector('#transitLeft'),right=document.querySelector('#transitRight');
const chapters={
  1:{code:'01 / LUNAR RECON',title:'接近月球',brief:'转动月球，寻找地形证据，锁定安全发射点',mode:'moon'},
  2:{code:'02 / ASCENT WINDOW',title:'月面发射准备',brief:'校准推力与离轨角度，等待安全窗口变绿',mode:'launch'},
  3:{code:'03 / TRANS-MARS INJECTION',title:'离开月球',brief:'飞船进入地火转移轨道，准备两次航向修正',mode:'cruise'},
  4:{code:'04 / ENTRY INTERFACE',title:'进入火星大气',brief:'隔热盾、降落伞、地形导航、空中吊车待命',mode:'edl'},
  5:{code:'05 / MARS SURFACE',title:'火星地表链路建立',brief:'驾驶巡视车检修基地，再穿过气闸恢复内部系统',mode:'mars'},
  6:{code:'06 / MISSION REPORT',title:'任务数据回传',brief:'成绩、证据与小队决策正在汇入课堂任务报告',mode:'report'}
};
let raf=0,started=0,duration=3600,active=false,current=chapters[1],revealFn=null,revealed=false,stars=[];

function resize(){if(!canvas)return;const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(innerWidth*d);canvas.height=Math.round(innerHeight*d);canvas.style.width=`${innerWidth}px`;canvas.style.height=`${innerHeight}px`;ctx.setTransform(d,0,0,d,0,0)}
function resetStars(){stars=Array.from({length:innerWidth>2600?520:280},()=>({x:Math.random()*innerWidth,y:Math.random()*innerHeight,z:Math.random(),s:.4+Math.random()*1.8,a:.15+Math.random()*.8}))}
function line(x1,y1,x2,y2,color,w=1){ctx.strokeStyle=color;ctx.lineWidth=w;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}
function glowCircle(x,y,r,color){const g=ctx.createRadialGradient(x-r*.3,y-r*.35,0,x,y,r*1.4);g.addColorStop(0,'#fff');g.addColorStop(.09,color);g.addColorStop(.58,color+'55');g.addColorStop(1,'transparent');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,r*1.4,0,Math.PI*2);ctx.fill()}
function starRush(p,speed=1){const cx=innerWidth*.5,cy=innerHeight*.48;ctx.save();for(const s of stars){const q=(s.z+p*speed)%1,stretch=Math.max(1,p*90*(1-q));const x=cx+(s.x-cx)*(1.1-q*.86),y=cy+(s.y-cy)*(1.1-q*.86);ctx.globalAlpha=s.a*(.35+p*.8);line(x,y,x+(x-cx)*stretch*.018,y+(y-cy)*stretch*.018,'#bff5ff',s.s)}ctx.restore()}
function drawMoon(p){const x=innerWidth*(.72-p*.08),y=innerHeight*.5,r=Math.min(innerWidth,innerHeight)*(.16+p*.05);glowCircle(x,y,r,'#b7c5ca');ctx.save();ctx.globalCompositeOperation='multiply';for(let i=0;i<22;i++){const a=i*2.39,rr=r*(.15+(i%7)/9);ctx.fillStyle=`rgba(18,24,27,${.07+(i%4)*.035})`;ctx.beginPath();ctx.arc(x+Math.cos(a)*rr,y+Math.sin(a)*rr,r*(.025+(i%5)*.012),0,Math.PI*2);ctx.fill()}ctx.restore();line(innerWidth*.12,innerHeight*.72,x-r*.7,y+r*.25,'rgba(97,233,255,.55)',2)}
function rocket(x,y,scale,angle=-.08){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale,scale);ctx.shadowColor='#7cecff';ctx.shadowBlur=18;ctx.fillStyle='#eaf6f8';ctx.beginPath();ctx.moveTo(0,-54);ctx.quadraticCurveTo(18,-33,15,18);ctx.lineTo(-15,18);ctx.quadraticCurveTo(-18,-33,0,-54);ctx.fill();ctx.fillStyle='#18282e';ctx.fillRect(-11,-4,22,18);ctx.fillStyle='#ff865e';ctx.beginPath();ctx.moveTo(-8,18);ctx.lineTo(0,68+Math.random()*34);ctx.lineTo(8,18);ctx.fill();ctx.restore()}
function drawLaunch(p){const ground=innerHeight*.79;const g=ctx.createLinearGradient(0,ground-90,0,innerHeight);g.addColorStop(0,'rgba(183,189,186,0)');g.addColorStop(1,'rgba(93,78,63,.65)');ctx.fillStyle=g;ctx.fillRect(0,ground-90,innerWidth,innerHeight-ground+90);const lift=Math.pow(p,1.4)*innerHeight*.78;rocket(innerWidth*.52,ground-lift,.9+p*.55,-.03);for(let i=0;i<12;i++)line(innerWidth*.52+(Math.random()-.5)*80,ground-lift+55,innerWidth*.52+(Math.random()-.5)*180,ground-lift+150+Math.random()*150,'rgba(255,153,91,.22)',2)}
function drawCruise(p){starRush(p,2.7);const x=innerWidth*(.16+p*.62),y=innerHeight*(.7-p*.37);ctx.save();ctx.translate(x,y);ctx.rotate(-.36);ctx.fillStyle='#dff8ff';ctx.shadowColor='#62e3ff';ctx.shadowBlur=25;ctx.beginPath();ctx.moveTo(72,0);ctx.lineTo(-35,-18);ctx.lineTo(-68,-6);ctx.lineTo(-72,6);ctx.lineTo(-35,18);ctx.closePath();ctx.fill();ctx.fillStyle='#ff8a5e';ctx.fillRect(-103,-9,38,18);ctx.restore();glowCircle(innerWidth*.83,innerHeight*.28,Math.min(innerWidth,innerHeight)*.09,'#dd714b')}
function drawEDL(p){const horizon=innerHeight*(.82-p*.08);const g=ctx.createLinearGradient(0,0,0,horizon);g.addColorStop(0,'rgba(6,10,20,.2)');g.addColorStop(.72,'rgba(255,90,42,.18)');g.addColorStop(1,'rgba(255,120,60,.72)');ctx.fillStyle=g;ctx.fillRect(0,0,innerWidth,horizon);ctx.fillStyle='#7c2d1f';ctx.fillRect(0,horizon,innerWidth,innerHeight-horizon);const x=innerWidth*(.72-p*.23),y=innerHeight*(.16+p*.46);ctx.save();ctx.translate(x,y);ctx.rotate(.58);ctx.fillStyle='#f4e0c5';ctx.beginPath();ctx.arc(0,0,36,Math.PI,Math.PI*2);ctx.lineTo(-36,0);ctx.fill();ctx.shadowColor='#ff5e2d';ctx.shadowBlur=45;ctx.strokeStyle='#ff8259';ctx.lineWidth=18;ctx.beginPath();ctx.arc(0,0,56,Math.PI*.92,Math.PI*2.08);ctx.stroke();ctx.restore()}
function drawMars(p){const horizon=innerHeight*.63;const g=ctx.createRadialGradient(innerWidth*.5,horizon,0,innerWidth*.5,horizon,innerWidth*.7);g.addColorStop(0,'#b95f3f');g.addColorStop(.45,'#6d2f25');g.addColorStop(1,'#130c0d');ctx.fillStyle=g;ctx.fillRect(0,horizon,innerWidth,innerHeight-horizon);ctx.fillStyle='rgba(3,8,12,.82)';ctx.fillRect(innerWidth*.46,horizon-85,innerWidth*.22,85);ctx.beginPath();ctx.arc(innerWidth*.57,horizon-85,85,Math.PI,0);ctx.fill();for(const x of [.39,.72]){line(innerWidth*x,horizon-10,innerWidth*x,horizon-180,'#0a1115',7);line(innerWidth*x,horizon-170,innerWidth*(x+.045),horizon-205,'#0a1115',5)}glowCircle(innerWidth*.5,horizon-16,10,'#73ffbf');ctx.strokeStyle='rgba(97,233,255,.32)';ctx.strokeRect(innerWidth*.26,horizon-235,innerWidth*.48,280)}
function drawReport(p){ctx.strokeStyle='rgba(97,233,255,.18)';for(let x=0;x<innerWidth;x+=innerWidth/16)line(x,0,x,innerHeight,'rgba(97,233,255,.1)');for(let y=0;y<innerHeight;y+=innerHeight/10)line(0,y,innerWidth,y,'rgba(97,233,255,.1)');for(let i=0;i<8;i++){const w=innerWidth*.025+i*innerWidth*.015;ctx.strokeStyle=`rgba(116,255,191,${.12+i*.06})`;ctx.strokeRect(innerWidth*.5-w,innerHeight*.5-w*.45,w*2,w*.9)}starRush(p,.45)}
function frame(now){if(!active)return;const p=Math.min(1,(now-started)/duration),e=1-Math.pow(1-p,3);ctx.clearRect(0,0,innerWidth,innerHeight);ctx.fillStyle='#010307';ctx.fillRect(0,0,innerWidth,innerHeight);starRush(p,.7);({moon:drawMoon,launch:drawLaunch,cruise:drawCruise,edl:drawEDL,mars:drawMars,report:drawReport}[current.mode]||drawCruise)(e);bar.style.width=`${Math.min(100,p*116)}%`;value.textContent=String(Math.round(p*100)).padStart(2,'0');if(!revealed&&p>.68){revealed=true;revealFn?.()}if(p<1)raf=requestAnimationFrame(frame);else finish()}
function finish(){active=false;overlay.classList.add('is-leaving');setTimeout(()=>{overlay.classList.remove('is-active','is-leaving');overlay.setAttribute('aria-hidden','true');document.body.classList.remove('mission-transitioning');ctx.clearRect(0,0,innerWidth,innerHeight)},720)}
function play(target,reveal){if(active){reveal?.();return}current=chapters[target]||chapters[1];revealFn=reveal;revealed=false;code.textContent=current.code;title.textContent=current.title;brief.textContent=current.brief;left.textContent=target===5?'MARS LOCAL / SOL 001':'SRT / MISSION CONTROL';right.textContent=target===2?'ASCENT CORRIDOR READY':'LINK ESTABLISHED';overlay.dataset.mode=current.mode;overlay.classList.remove('is-leaving');overlay.classList.add('is-active');overlay.setAttribute('aria-hidden','false');document.body.classList.add('mission-transitioning');bar.style.width='0';resize();resetStars();active=true;started=performance.now();duration=target===4?4100:3500;cancelAnimationFrame(raf);raf=requestAnimationFrame(frame)}
function launch(){return new Promise(resolve=>{const old=duration;current={code:'T−00:03 / LUNAR ASCENT',title:'月面点火',brief:'上升器离开发射台，正在建立月球安全轨道',mode:'launch'};revealFn=null;revealed=true;code.textContent=current.code;title.textContent=current.title;brief.textContent=current.brief;left.textContent='PAD / SHACKLETON RIM';right.textContent='ORBIT INSERTION';overlay.dataset.mode='launch';overlay.classList.remove('is-leaving');overlay.classList.add('is-active');overlay.setAttribute('aria-hidden','false');document.body.classList.add('mission-transitioning');bar.style.width='0';resize();resetStars();active=true;started=performance.now();duration=5200;cancelAnimationFrame(raf);raf=requestAnimationFrame(frame);setTimeout(()=>{duration=old;resolve()},5700)})}
addEventListener('resize',()=>{if(active){resize();resetStars()}});
export {play,launch};
